namespace ark { namespace {
using V=arkjson::Value;
const V& field(const V& v,const char* k){static V nil;auto* p=v.find(k);return p?*p:nil;}
std::string text(const V& v,const char* k){return field(v,k).asStr();}
V number(u64 n){return V::makeNum(static_cast<double>(n));}
void canonical(V& value){if(value.t==V::Obj){for(auto& kv:value.obj)canonical(kv.second);std::sort(value.obj.begin(),value.obj.end(),[](const auto& a,const auto& b){return a.first<b.first;});}else if(value.t==V::Arr)for(auto& item:value.arr)canonical(item);}
std::string canonicalText(V value){canonical(value);return value.dump();}
V strings(const std::set<std::string>& values){V a=V::makeArr();for(const auto& s:values)a.arr.push_back(V::makeStr(s));return a;}
V featureSource(const Feature& f){V row=V::makeObj(),p=V::makeObj(),inputs=V::makeArr();std::map<std::string,std::string> sorted(f.p.begin(),f.p.end());for(const auto& kv:sorted)p.set(kv.first,V::makeStr(kv.second));for(auto id:f.inputs)inputs.arr.push_back(number(id));row.set("name",V::makeStr(f.name));row.set("type",V::makeStr(featureTypeName(f.type)));row.set("parameters",p);row.set("inputs",inputs);row.set("native",f.nativeSpec);row.set("part",f.part);row.set("material",V::makeStr(f.material));row.set("suppressed",V::makeBool(f.suppressed));row.set("source",f.sourceData);row.set("appearance",f.appearance);row.set("classification",f.classification);row.set("manufacturing_route",V::makeStr(f.manufacturingRoute));row.set("manufacturing_process",f.manufacturingProcess);canonical(row);return row;}
std::string sourceHash(const Document& d){return iterationSha256(iterationAuthoring(d).dump());}
V delta(const V& a,const V& b){V out=V::makeArr();std::set<std::string> keys;for(const auto& kv:a.obj)keys.insert(kv.first);for(const auto& kv:b.obj)keys.insert(kv.first);for(const auto& key:keys)if(canonicalText(field(a,key.c_str()))!=canonicalText(field(b,key.c_str()))){V row=V::makeObj();row.set("field",V::makeStr(key));row.set("before",field(a,key.c_str()));row.set("after",field(b,key.c_str()));out.arr.push_back(row);}return out;}
V parameters(const Document& d){V out=V::makeObj();for(const auto& p:d.params)out.set(p.name,V::makeStr(p.expr));return out;}
V bodyInfo(const Document& d,u64 id){V out=V::makeObj();for(const auto& b:d.evalBodies)if(b.id==id){const auto* topology=b.nativeData.find("topology");const auto* hash=topology?topology->find("brep_sha256"):nullptr;if(const auto* report=b.nativeData.find("report")){for(const char* key:{"bounds_mm","volume_mm3"})if(const auto* value=report->find(key))out.set(key,*value);}if(hash){out.set("geometry_sha256",*hash);out.set("geometry_authority",V::makeStr("native_brep"));}else{auto mesh=b.tessellate(d.tessOpt);std::string bytes(reinterpret_cast<const char*>(mesh.pos.data()),mesh.pos.size()*sizeof(float));bytes.append(reinterpret_cast<const char*>(mesh.idx.data()),mesh.idx.size()*sizeof(u32));out.set("geometry_sha256",V::makeStr(iterationSha256(bytes)));out.set("geometry_authority",V::makeStr("display_mesh_only"));}break;}for(const auto& r:d.lastResults)if(r.id==id){out.set("ok",V::makeBool(r.ok));if(!r.ok)out.set("error",V::makeStr(r.error));}return out;}
V bomRows(const Document& d,u64 revision){try{return inspectBom(d,revision);}catch(const std::exception& e){V o=V::makeObj();o.set("unavailable",V::makeStr(e.what()));return o;}}
V indexedBom(const V& bom){V out=V::makeObj();for(const auto& row:field(bom,"items").arr)out.set(std::to_string((u64)field(row,"feature").num),row);return out;}
V placements(const Document& d){V out=V::makeObj();if(d.assembly.empty())return out;std::vector<AssemblyPlacement> places;std::string error;if(!resolveAssembly(d,places,error)){out.set("error",V::makeStr(error));return out;}for(const auto& p:places){V rows=field(out,std::to_string(p.feature).c_str());if(rows.t!=V::Obj)rows=V::makeObj();V row=V::makeObj(),matrix=V::makeArr();for(double x:p.world.m)matrix.arr.push_back(V::makeNum(x));row.set("transform",matrix);row.set("visible",V::makeBool(p.visible));row.set("name",V::makeStr(p.name));rows.set(std::to_string(p.node)+":"+std::to_string(p.copy),row);out.set(std::to_string(p.feature),rows);}return out;}
void guardRevision(const AgentSession& s,const V& args){const auto& r=field(args,"expected_revision");if(r.t!=V::Num||r.num<0||std::floor(r.num)!=r.num||r.num!=static_cast<double>(s.revision))throw std::runtime_error("Design review requires current expected_revision; inspect again after edits");}
void rejectToleranceChanges(const V& before,const V& after,bool complete=false){if(complete){for(const auto& kv:before.obj)if(!after.find(kv.first.c_str())){auto key=kv.first;std::transform(key.begin(),key.end(),key.begin(),[](unsigned char c){return (char)std::tolower(c);});if(key.find("tolerance")!=std::string::npos||key.find("fuzzy")!=std::string::npos||key=="tol"||(key.size()>4&&key.substr(key.size()-4)=="_tol"))throw std::runtime_error("Repair cannot remove explicit kernel tolerances");if(kv.second.t==V::Obj)rejectToleranceChanges(kv.second,V(),true);}}for(const auto& kv:after.obj){auto name=kv.first;std::transform(name.begin(),name.end(),name.begin(),[](unsigned char c){return (char)std::tolower(c);});const auto& prior=field(before,kv.first.c_str());if((name.find("tolerance")!=std::string::npos||name.find("fuzzy")!=std::string::npos||name=="tol"||(name.size()>4&&name.substr(name.size()-4)=="_tol"))&&prior.dump()!=kv.second.dump())throw std::runtime_error("Repair cannot change kernel tolerances; correct geometry or references explicitly");if(complete&&prior.t==V::Obj&&kv.second.t!=V::Obj)rejectToleranceChanges(prior,V(),true);if(kv.second.t==V::Obj)rejectToleranceChanges(prior,kv.second,complete);else if(kv.second.t==V::Arr)for(size_t i=0;i<kv.second.arr.size();++i)rejectToleranceChanges(prior.t==V::Arr&&i<prior.arr.size()?prior.arr[i]:V(),kv.second.arr[i]);}}
V rejectedEdit(AgentSession& session,const std::string& id,u64& feature){
    V request=V::makeObj();request.set("id",V::makeStr(id));const auto receipt=session.failureInfo(request);const auto record=field(receipt,"record");
    if(field(record,"baseline_revision").num!=(double)session.revision)throw std::runtime_error("Rejected operation belongs to another revision; inspect and author a fresh correction");
    const auto& commands=field(field(record,"replay_request"),"commands");if(commands.t!=V::Arr||commands.arr.size()!=1||text(commands.arr[0],"op")!="feature.edit")throw std::runtime_error("Guided rejected-operation repair requires one retained feature.edit; use explicit authoring for a multi-command failure");
    for(const auto& kv:commands.arr[0].obj)if(kv.first!="op"&&kv.first!="id"&&kv.first!="p"&&kv.first!="native"&&kv.first!="inputs")throw std::runtime_error("Guided rejected-operation repair covers explicit dimensions, references and dependencies; use ordinary authoring for other fields");
    const auto& target=field(commands.arr[0],"id");feature=0;if(target.t==V::Num&&target.num>=1&&target.num<=9007199254740991.&&std::floor(target.num)==target.num)feature=(u64)target.num;else if(target.t==V::Str)for(const auto& f:session.document.features)if(f.name==target.str){if(feature)throw std::runtime_error("Ambiguous failed feature name");feature=f.id;}
    if(!feature||!session.document.find(feature))throw std::runtime_error("The rejected feature no longer exists");return record;
}
void appendRejectedEdits(AgentSession& session,V& diagnostics){
    V failures=field(diagnostics,"failures");const auto inventory=session.failureInfo(V::makeObj());diagnostics.set("rejected_operations",field(inventory,"records"));
    for(const auto& entry:field(inventory,"records").arr){u64 id=0;V record;try{record=rejectedEdit(session,text(entry,"id"),id);}catch(const std::exception&){continue;}const auto* f=session.document.find(id);V row=featureSource(*f);row.set("id",number(id));row.set("failure_id",field(record,"id"));row.set("diagnostic_origin",V::makeStr("rejected_edit; current geometry remains unchanged"));const auto& command=field(field(record,"replay_request"),"commands").arr[0];row.set("attempted_command",command);V p=field(row,"parameters");for(const auto& kv:field(command,"p").obj)p.set(kv.first,kv.second.t==V::Str?kv.second:V::makeStr(kv.second.dump()));row.set("parameters",p);for(const char* key:{"native","inputs"})if(const auto* value=command.find(key))row.set(key,*value);const auto error=field(record,"error");row.set("error",V::makeStr(field(error,"error").t==V::Str?text(error,"error"):error.dump()));V earlier=V::makeArr(),dependents=V::makeArr();for(const auto& candidate:session.document.features){if(candidate.id==id)break;V item=V::makeObj();item.set("id",number(candidate.id));item.set("name",V::makeStr(candidate.name));earlier.arr.push_back(item);}for(const auto& child:session.document.features)if(std::find(child.inputs.begin(),child.inputs.end(),id)!=child.inputs.end())dependents.arr.push_back(number(child.id));row.set("earlier_dependencies",earlier);row.set("dependents",dependents);row.set("guidance",V::makeStr("Correct the retained rejected edit. The current valid design is preserved until a reviewed candidate is applied."));failures.arr.push_back(row);}
    diagnostics.set("failures",failures);
}
}
arkjson::Value compareDesignRevisions(const Document& source,u64 revision,const std::string& beforeId,const std::string& afterId){
    if(beforeId.empty())throw std::runtime_error("Choose a retained before_id from history_info");
    Document before,after;iterationRestore(source,beforeId,before);if(afterId=="current")after=source.authoringCopy();else iterationRestore(source,afterId,after);
    before.recompute();after.recompute();const auto beforePlaces=placements(before),afterPlaces=placements(after);V out=V::makeObj(),rows=V::makeArr();std::set<u64> ids;for(const auto& f:before.features)ids.insert(f.id);for(const auto& f:after.features)ids.insert(f.id);size_t added=0,removed=0,changed=0,unchanged=0;
    for(auto id:ids){auto* a=before.find(id);auto* b=after.find(id);V av=a?featureSource(*a):V(),bv=b?featureSource(*b):V();V ag=a?bodyInfo(before,id):V(),bg=b?bodyInfo(after,id):V();const bool geometry=text(ag,"geometry_sha256")!=text(bg,"geometry_sha256")||field(ag,"ok").dump()!=field(bg,"ok").dump();const auto occurrenceChanges=delta(field(beforePlaces,std::to_string(id).c_str()),field(afterPlaces,std::to_string(id).c_str()));std::string status=!a?"added":!b?"removed":av.dump()!=bv.dump()||geometry||!occurrenceChanges.arr.empty()?"changed":"unchanged";if(status=="added")++added;else if(status=="removed")++removed;else if(status=="changed")++changed;else ++unchanged;V row=V::makeObj();row.set("id",number(id));row.set("name",V::makeStr(b?b->name:a->name));row.set("status",V::makeStr(status));row.set("geometry_changed",V::makeBool(geometry));row.set("changes",delta(av,bv));row.set("occurrence_changes",occurrenceChanges);row.set("geometry_metrics_changes",delta(ag,bg));row.set("parameter_changes",delta(field(av,"parameters"),field(bv,"parameters")));row.set("before_geometry",ag);row.set("after_geometry",bg);rows.arr.push_back(row);}
    const auto ba=iterationAuthoring(before),aa=iterationAuthoring(after);out.set("format",V::makeStr("ark.design-review.v1"));out.set("revision",number(revision));out.set("before_id",V::makeStr(beforeId));out.set("after_id",V::makeStr(afterId));out.set("source_sha256",V::makeStr(sourceHash(source)));out.set("hash_scope",V::makeStr("reconstructed authoring; retained identifiers use current allocator high-water marks"));out.set("before_sha256",V::makeStr(sourceHash(before)));out.set("after_sha256",V::makeStr(sourceHash(after)));out.set("features",rows);out.set("added",number(added));out.set("removed",number(removed));out.set("changed",number(changed));out.set("unchanged",number(unchanged));out.set("parameter_changes",delta(parameters(before),parameters(after)));out.set("placement_comparison_available",V::makeBool(!beforePlaces.find("error")&&!afterPlaces.find("error")));if(beforePlaces.find("error"))out.set("before_placement_error",field(beforePlaces,"error"));if(afterPlaces.find("error"))out.set("after_placement_error",field(afterPlaces,"error"));out.set("assembly_changed",V::makeBool(field(ba,"assembly").dump()!=field(aa,"assembly").dump()));out.set("assembly_before",field(ba,"assembly"));out.set("assembly_after",field(aa,"assembly"));const auto beforeBom=bomRows(before,revision),afterBom=bomRows(after,revision);out.set("bom_before",beforeBom);out.set("bom_after",afterBom);out.set("bom_changes",delta(indexedBom(beforeBom),indexedBom(afterBom)));out.set("display_only",V::makeBool(true));return out;
}
arkjson::Value diagnoseDesignFeatures(const Document& source,u64 revision){
    Document evaluated=source.authoringCopy();evaluated.recompute();V out=V::makeObj(),rows=V::makeArr();for(const auto& f:evaluated.features){const FeatureResult* result=nullptr;for(const auto& r:evaluated.lastResults)if(r.id==f.id)result=&r;V missing=V::makeArr(),earlier=V::makeArr(),dependents=V::makeArr();for(auto id:f.inputs)if(!evaluated.find(id))missing.arr.push_back(number(id));for(const auto& candidate:evaluated.features){if(candidate.id==f.id)break;V item=V::makeObj();item.set("id",number(candidate.id));item.set("name",V::makeStr(candidate.name));earlier.arr.push_back(item);}for(const auto& child:evaluated.features)if(std::find(child.inputs.begin(),child.inputs.end(),f.id)!=child.inputs.end())dependents.arr.push_back(number(child.id));if((!result||result->ok)&&missing.arr.empty())continue;V row=featureSource(f);row.set("id",number(f.id));row.set("error",V::makeStr(result?result->error:"Missing dependency"));row.set("missing_inputs",missing);row.set("earlier_dependencies",earlier);row.set("dependents",dependents);row.set("guidance",V::makeStr("Inspect the reported error. Correct explicit parameter expressions, native references or earlier inputs, then prepare_repair. No deletion, suppression or automatic tolerance change is proposed."));rows.arr.push_back(row);}
    out.set("format",V::makeStr("ark.design-diagnostics.v1"));out.set("revision",number(revision));out.set("source_sha256",V::makeStr(sourceHash(source)));out.set("failures",rows);return out;
}
bool callDesignReviewTool(AgentSession& session,const std::string& tool,const V& args,V& result){
    if(tool!="design_review")return false;guardRevision(session,args);for(const auto& kv:args.obj)if(kv.first!="action"&&kv.first!="expected_revision"&&kv.first!="before_id"&&kv.first!="after_id"&&kv.first!="source_sha256"&&kv.first!="id"&&kv.first!="failure_id"&&kv.first!="command")throw std::runtime_error("Unknown design_review field: "+kv.first);const auto action=text(args,"action");
    if(action=="compare")result=compareDesignRevisions(session.document,session.revision,text(args,"before_id"),args.find("after_id")?text(args,"after_id"):"current");
    else if(action=="diagnose"){result=diagnoseDesignFeatures(session.document,session.revision);appendRejectedEdits(session,result);}
    else if(action=="prepare_repair"){
        if(text(args,"source_sha256")!=sourceHash(session.document))throw std::runtime_error("Repair source fingerprint changed; diagnose again");const auto& idValue=field(args,"id");if(idValue.t!=V::Num||idValue.num<1||idValue.num>9007199254740991.||std::floor(idValue.num)!=idValue.num)throw std::runtime_error("Repair requires numeric feature id");const auto id=static_cast<u64>(idValue.num);auto diagnostics=diagnoseDesignFeatures(session.document,session.revision);bool found=false;if(args.find("failure_id")){u64 rejectedId=0;rejectedEdit(session,text(args,"failure_id"),rejectedId);if(rejectedId!=id)throw std::runtime_error("Repair target differs from the retained rejected edit");found=true;}for(const auto& r:field(diagnostics,"failures").arr)if(field(r,"id").num==idValue.num)found=true;if(!found)throw std::runtime_error("Selected feature is not failing and no current retained failure_id was supplied; use ordinary authoring for a normal edit");
        V command=field(args,"command");if(command.t!=V::Obj||text(command,"op")!="feature.edit"||field(command,"id").t!=V::Num||field(command,"id").num!=idValue.num)throw std::runtime_error("Repair command must edit exactly the inspected feature");for(const auto& kv:command.obj)if(kv.first!="op"&&kv.first!="id"&&kv.first!="p"&&kv.first!="native"&&kv.first!="inputs")throw std::runtime_error("Repair accepts explicit p, native or inputs only; deletion and suppression are not repairs");const auto* sourceFeature=session.document.find(id);rejectToleranceChanges(field(featureSource(*sourceFeature),"parameters"),field(command,"p"));if(command.find("native"))rejectToleranceChanges(sourceFeature->nativeSpec,field(command,"native"),true);if(command.obj.size()<3)throw std::runtime_error("Repair contains no correction");V preview=V::makeObj(),commands=V::makeArr();commands.arr.push_back(command);preview.set("expected_revision",number(session.revision));preview.set("commands",commands);preview.set("detail",V::makeStr("changes"));auto response=session.call("doc_preview",preview);if(field(response,"isError").b)throw std::runtime_error(response.dump());result=field(response,"structuredContent");if(!field(result,"valid").b||!field(result,"candidate_cached").b||text(result,"candidate_id").empty())throw std::runtime_error("Repair rejected by full-document validation: "+result.dump());result.set("repair_feature",number(id));result.set("source_sha256",field(diagnostics,"source_sha256"));
    }else throw std::runtime_error("Unknown design_review action");return true;
}
void appendDesignReviewTools(V& tools){V tool=V::makeObj(),schema,annotations=V::makeObj();tool.set("name",V::makeStr("design_review"));tool.set("description",V::makeStr("Compare retained history revisions without restoring; diagnose failed features and explicitly preview parameter/reference/input repairs. All actions require current expected_revision. prepare_repair requires diagnose source_sha256 and one feature.edit command; rejected edits also require their current failure_id; publish the reviewed preview through doc_apply. No deletion, suppression, relaxed tolerances or automatic substitutions."));arkjson::parse(R"JSON({"type":"object","properties":{"action":{"type":"string","enum":["compare","diagnose","prepare_repair"]},"expected_revision":{"type":"integer","minimum":0},"before_id":{"type":"string"},"after_id":{"type":"string"},"source_sha256":{"type":"string"},"failure_id":{"type":"string"},"id":{"type":"integer","minimum":1},"command":{"type":"object"}},"required":["action","expected_revision"],"additionalProperties":false})JSON",schema);tool.set("inputSchema",schema);annotations.set("readOnlyHint",V::makeBool(false));tool.set("annotations",annotations);tools.arr.push_back(tool);}
}
